// Webhook POST: datos en .body cuando Content-Type es application/json
const body = $input.first().json.body || $input.first().json;

// Validar campos obligatorios
const required = ['name', 'email', 'date', 'time', 'guests'];
const missing = required.filter(f => !body[f] || String(body[f]).trim() === '');

// Validar formato de email
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email || '');

// Formatear fecha legible en español
let formattedDate = body.date || '';
try {
  formattedDate = new Date(body.date).toLocaleDateString('es-ES', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
  });
} catch (_) {}

// ID único de la reserva
const reservationId = 'RSV-' + new Date().getFullYear() + '-' + Date.now().toString().slice(-6);

return [{
  json: {
    isValid: missing.length === 0 && emailOk,
    missingFields: missing,
    emailOk,
    reservationId,
    name:          String(body.name  || '').trim(),
    email:         String(body.email || '').trim().toLowerCase(),
    date:          body.date,
    formattedDate,
    time:          body.time,
    guests:        parseInt(body.guests) || 1,
    message:       String(body.message || '').trim(),
    createdAt:     new Date().toISOString(),
    status:        'pendiente'
  }
}];

